// The skall tuvali's chat walls (docs/design/sistem/varlik/desen-<dm|masa|mekan>-<acik|koyu>.svg and
// the boards' `.wall` grounds) → apps/mobile/src/theme/chatWalls.generated.ts: each tile's inner
// SVG (300 × 300) and its ground. `node --experimental-strip-types scripts/sistem/walls.ts`; the
// test (walls.test.ts) checks the generated file against the canvas files.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

export const WALL_KINDS = ['dm', 'masa', 'mekan'] as const;
const SCHEMES = { light: 'acik', dark: 'koyu' } as const;
// Each board's `.wall` ground (DmÜ, Masa sohbeti, Mekan sohbeti; acik and koyu).
const BOARDS = { dm: 'Dm', masa: 'MasaSohbeti', mekan: 'MekanSohbeti' } as const;

function inner(svg: string): string {
  const open = svg.indexOf('>', svg.indexOf('<svg')) + 1;
  const close = svg.lastIndexOf('</svg>');
  return svg.slice(open, close).trim();
}

function grounds(root: string, board: string): { light: string; dark: string } {
  const html = readFileSync(join(root, 'docs/design/sistem/ekran', `${board}.html`), 'utf8');
  const light = /\n\.wall\{[^}]*,(#[0-9A-Fa-f]{6})\}/.exec(html)?.[1];
  const dark = /\.dark \.wall\{[^}]*,(#[0-9A-Fa-f]{6})\}/.exec(html)?.[1];
  if (!light || !dark) throw new Error(`${board}: no wall ground`);
  return { light, dark };
}

export function wallsSource(root: string): string {
  const entries = WALL_KINDS.map((kind) => {
    const g = grounds(root, BOARDS[kind]);
    const tiles = Object.entries(SCHEMES).map(([scheme, file]) => {
      const svg = readFileSync(
        join(root, 'docs/design/sistem/varlik', `desen-${kind}-${file}.svg`),
        'utf8',
      );
      return `    ${scheme}: ${JSON.stringify(inner(svg))},`;
    });
    return `  ${kind}: {\n    ground: { light: '${g.light}', dark: '${g.dark}' },\n    tile: {\n  ${tiles.join('\n  ')}\n    },\n  },`;
  });
  return `// Generated by scripts/sistem/walls.ts from the skall tuvali (docs/design/sistem/varlik). Do not\n// edit; run the script.\nexport const CHAT_WALLS = {\n${entries.join('\n')}\n} as const;\n\nexport type ChatWallKind = keyof typeof CHAT_WALLS;\n`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const root = process.cwd();
  writeFileSync(join(root, 'apps/mobile/src/theme/chatWalls.generated.ts'), wallsSource(root));
}
